// Calcular días desde último backup
const diasDesdeBackup = (fecha) => {
  if (!fecha) return 9999;
  const diff = new Date() - new Date(fecha);
  return Math.floor(diff / (1000 * 60 * 60 * 24));
};

const generarNotificaciones = (cliente) => {
  const notifs = {
    C001:[
      { id:"N001", fecha:"2026-03-28", tipo:"MANTENIMIENTO", urgencia:"ALTA", titulo:"Mantenimiento preventivo vencido — Robot Línea B", mensaje:"El Robot Soldadura Línea B tiene el mantenimiento preventivo vencido desde Diciembre 2025. Se recomienda coordinar revisión con Robot-IK a la brevedad.", leida:false },
    ],
    C002:[
      { id:"N003", fecha:"2026-03-25", tipo:"INFO", urgencia:"BAJA", titulo:"Actualización de firmware disponible — YRC1000", mensaje:"Robot-IK informa que hay una nueva versión de firmware disponible para el controlador YRC1000. Contacte a soporte para coordinar la actualización.", leida:false },
    ],
  };
  const base = notifs[cliente.id] || [];
  // Agregar notificación automática si backup > 60 días
  cliente.robots.forEach(id => {
    const robot = ROBOTS[id];
    const dias = diasDesdeBackup(robot.ultimoBackup);
    if (dias > 60) {
      base.push({
        id: `NBKP-${id}`, fecha: new Date().toISOString().slice(0,10),
        tipo:"BACKUP", urgencia: dias > 90 ? "ALTA" : "MEDIA",
        titulo:`Backup requerido — ${robot.nombre}`,
        mensaje:`Han pasado ${dias === 9999 ? "más de 60" : dias} días desde el último backup del controlador ${robot.controlador}. Se recomienda realizar un backup completo y cargarlo en el portal para mantener la continuidad operativa.`,
        leida:false,
      });
    }
  });
  return base;
};

