const Btn = ({ children, onClick, color=C.cyan, variant="primary", small=false, style={}, disabled=false }) => {
  const [h,setH] = useState(false);
  const p = variant==="primary";
  return (
    <button onClick={onClick} disabled={disabled}
      onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
      style={{ fontFamily:"'Rajdhani',sans-serif",fontWeight:700,fontSize:small?13:15,letterSpacing:"0.08em",
        padding:small?"6px 14px":"10px 22px",borderRadius:5,cursor:disabled?"not-allowed":"pointer",
        border:`1px solid ${color}`,background:p?(h?color:`${color}22`):"transparent",
        color:p?(h?C.bg:color):(h?color:C.textSecondary),transition:"all 0.2s ease",
        opacity:disabled?0.4:1,...style }}>{children}</button>
  );
};

