// ─── CLOCK 24H ─────────────────────────────────────────────────────────────────
const Clock = ({ color=C.textSecondary, style={} }) => {
  const [t,setT] = useState(new Date());
  useEffect(()=>{ const i=setInterval(()=>setT(new Date()),1000); return()=>clearInterval(i); },[]);
  const h = String(t.getHours()).padStart(2,'0');
  const m = String(t.getMinutes()).padStart(2,'0');
  const s = String(t.getSeconds()).padStart(2,'0');
  const fecha = t.toLocaleDateString("es-AR",{weekday:"short",day:"2-digit",month:"short",year:"numeric"});
  return <span style={{ fontFamily:"'Share Tech Mono',monospace",fontSize:13,color,...style }}>{h}:{m}:{s} — {fecha}</span>;
};

