// ─── LOGIN ─────────────────────────────────────────────────────────────────────
const LoginScreen = ({ onLogin }) => {
  const [email,setEmail] = useState("");
  const [pass,setPass] = useState("");
  const [error,setError] = useState("");
  const [loading,setLoading] = useState(false);
  const [showPass,setShowPass] = useState(false);

  const handleLogin = () => {
    setLoading(true); setError("");
    setTimeout(()=>{
      const c = CLIENTES.find(c=>c.email===email&&c.password===pass);
      if(c) onLogin(c); else setError("Credenciales inválidas. Verifique su usuario y contraseña.");
      setLoading(false);
    },900);
  };

  return (
    <div style={{ height:"100vh",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",background:C.bg,position:"relative",overflow:"hidden" }}>
      <div style={{ position:"absolute",top:0,left:0,right:0,height:2,background:`linear-gradient(90deg,transparent,${C.cyan}33,transparent)`,animation:"scan-line 6s linear infinite",pointerEvents:"none" }} />
      <div style={{ position:"absolute",inset:0,opacity:0.03,backgroundImage:`linear-gradient(${C.cyan} 1px,transparent 1px),linear-gradient(90deg,${C.cyan} 1px,transparent 1px)`,backgroundSize:"40px 40px" }} />
      {[0,1,2,3].map(i=>(
        <div key={i} style={{ position:"absolute",top:i<2?24:"auto",bottom:i>=2?24:"auto",left:i%2===0?24:"auto",right:i%2===1?24:"auto",width:40,height:40,
          borderTop:i<2?`2px solid ${C.cyan}33`:"none",borderBottom:i>=2?`2px solid ${C.cyan}33`:"none",
          borderLeft:i%2===0?`2px solid ${C.cyan}33`:"none",borderRight:i%2===1?`2px solid ${C.cyan}33`:"none" }} />
      ))}
      <div style={{ width:420,animation:"fade-in-up 0.6s ease forwards",background:C.surface,border:`1px solid ${C.border}`,borderRadius:12,overflow:"hidden",boxShadow:`0 0 60px ${C.cyan}11,0 24px 48px #00000066` }}>
        <div style={{ padding:"32px 32px 24px",background:`linear-gradient(135deg,${C.surface2} 0%,${C.surface} 100%)`,borderBottom:`1px solid ${C.border}`,textAlign:"center" }}>
          <div style={{ display:"flex",justifyContent:"center",marginBottom:8 }}><RobotIKLogo height={70} showSubtitle={true} /></div>
          <div style={{ marginTop:10 }}><Clock color={C.textMuted} /></div>
        </div>
        <div style={{ padding:"28px 32px 32px" }}>
          <p style={{ fontSize:14,color:C.textSecondary,marginBottom:24,textAlign:"center" }}>Ingrese con sus credenciales para acceder al seguimiento de sus equipos Yaskawa.</p>
          <label style={{ fontSize:12,color:C.textMuted,letterSpacing:"0.1em",textTransform:"uppercase",display:"block",marginBottom:6 }}>ID Operador / Email</label>
          <input type="email" value={email} onChange={e=>setEmail(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleLogin()} placeholder="usuario@empresa.com"
            style={{ width:"100%",padding:"11px 14px",marginBottom:18,background:C.bg,border:`1px solid ${C.border}`,borderRadius:5,color:C.textPrimary,fontFamily:"'Share Tech Mono',monospace",fontSize:14,outline:"none" }}
            onFocus={e=>e.target.style.borderColor=C.cyan} onBlur={e=>e.target.style.borderColor=C.border} />
          <label style={{ fontSize:12,color:C.textMuted,letterSpacing:"0.1em",textTransform:"uppercase",display:"block",marginBottom:6 }}>Contraseña</label>
          <div style={{ position:"relative",marginBottom:24 }}>
            <input type={showPass?"text":"password"} value={pass} onChange={e=>setPass(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleLogin()} placeholder="••••••••"
              style={{ width:"100%",padding:"11px 40px 11px 14px",background:C.bg,border:`1px solid ${C.border}`,borderRadius:5,color:C.textPrimary,fontFamily:"'Share Tech Mono',monospace",fontSize:14,outline:"none" }}
              onFocus={e=>e.target.style.borderColor=C.cyan} onBlur={e=>e.target.style.borderColor=C.border} />
            <button onClick={()=>setShowPass(!showPass)} style={{ position:"absolute",right:12,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",cursor:"pointer",color:C.textMuted,fontSize:16 }}>{showPass?"🙈":"👁"}</button>
          </div>
          {error && <div style={{ padding:"10px 14px",marginBottom:18,background:`${C.red}15`,border:`1px solid ${C.red}44`,borderRadius:5,color:C.red,fontSize:13 }}>{error}</div>}
          <Btn onClick={handleLogin} disabled={loading} style={{ width:"100%",justifyContent:"center" }}>{loading?"VERIFICANDO...":"INGRESAR AL PORTAL"}</Btn>
          <div style={{ textAlign:"center",marginTop:20 }}>
            <span style={{ fontSize:12,color:C.textMuted }}>¿Problemas de acceso? <span style={{ color:C.cyan,cursor:"pointer",fontWeight:600 }}>Contactar a Robot-IK</span></span>
          </div>
          <div style={{ marginTop:24,padding:"12px 14px",background:C.surface2,borderRadius:5,border:`1px solid ${C.border}` }}>
            <div style={{ fontSize:11,color:C.textMuted,marginBottom:6,letterSpacing:"0.1em",textTransform:"uppercase" }}>Demo</div>
            <div style={{ fontSize:12,fontFamily:"'Share Tech Mono',monospace",color:C.textSecondary,lineHeight:1.8 }}>
              soporte@acerosdelsur.com / demo1234<br/>operador@metalurgicaperez.com / perez2024
            </div>
          </div>
        </div>
      </div>
      <div style={{ marginTop:20,fontSize:11,color:C.textMuted,letterSpacing:"0.1em" }}>© 2026 ROBOT-IK — Armstrong, Santa Fe — Servicio Confidencial</div>
    </div>
  );
};

